mapper.select:
select
mn.*,
sf.T_Name as tName
from Outline_Datasource_Temp mn
left join SYS_FileTemplate sf on mn.T_Code = sf.T_Code

    
        and mn.id = #{params.id}
    
    
        and mn.Od_Id = #{params.odId}
    
    
        and mn.T_Code = #{params.tCode}
    
    
        and mn.T_Name = #{params.tName}
